const { Pool } = require("pg"); const dns = require("dns").promises; let poolPromise = null; async function buildPool() { const original = new URL(process.env.DATABASE_URL); const hostname = original.hostname; let ipv4Host = hostname; try { const addresses = await dns.resolve4(hostname); if (addresses && addresses.length > 0) { ipv4Host = addresses[0]; } } catch (err) { console.error("Não foi possível resolver IPv4 para", hostname, "- usando hostname original.", err.message); } return new Pool({ host: ipv4Host, port: Number(original.port) || 5432, user: decodeURIComponent(original.username), password: decodeURIComponent(original.password), database: original.pathname.replace(/^\//, "") || "postgres", ssl: { rejectUnauthorized: false, servername: hostname }, }); } function getPool() { if (!poolPromise) poolPromise = buildPool(); return poolPromise; } async function query(text, params) { const pool = await getPool(); return pool.query(text, params); } module.exports = { query, getPool };
